        FifoStore fifo = new FifoStore();
        LifoStore lifo = new LifoStore();
        for (int i = 0; i < args.length; i++) {
            fifo.put(args[i]);
            lifo.put(args[i]);
        }
        printData(fifo);
        printData(lifo);
    }
    private static void printData([d] store) {
        int size = store.size();
        for (int i = 0; i < size; i++)
            System.out.print(i + ": " + store.get() + " ");
        System.out.println();
    }
}

